const dialog=document.querySelector('#details');const title=document.querySelector('#dialog-title');const body=document.querySelector('#dialog-body');function show(topic,text){title.textContent=topic;body.replaceChildren();const p=document.createElement('p');p.textContent=text;body.append(p);dialog.showModal()}document.querySelectorAll('[data-topic]').forEach(el=>el.addEventListener('click',e=>{e.preventDefault();const t=el.dataset.topic;if(t==='Platforms'){document.querySelector('#platforms').scrollIntoView({behavior:'smooth'});return}const copy={'Sign In':'This is a recreation of the 2001 homepage. Original member accounts are not connected.','Members Only':'The GameCube and Xbox giveaway shown on this page is historical and is no longer open.','Link to Us':'Copy this page’s address from your browser to share this recreation.','Privacy Statement':'This static recreation does not send your email address or store member information.','Terms of Service':'This is an independent visual recreation of a historical website. Original promotions are not active.','Contact Us':'This recreated page has no connected support inbox.','Help':'Choose a platform, explore the original navigation, or use Back to Top. Press Escape to close any panel.','New Stuff':'The news and promotions on the homepage reproduce the supplied 2001 reference. There is no live news feed connected.','About Us':'A recreation of the classic CheatCodes.com homepage, preserving the original chrome artwork and console graphics with semantic HTML, Kujo SSG, and SiteKit.'};show(t,copy[t]||'You’re viewing the '+t+' section of this historical design recreation. The original game database and account services are not connected.')}));document.querySelector('#newsletter').addEventListener('submit',e=>{e.preventDefault();show('Thanks for visiting!','This is a historical signup form demonstration. Your email has not been sent or saved.');e.target.reset()});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});function scale(){const scale=Math.min(1,innerWidth/830);document.querySelector('.site').style.transform=`scale(${scale})`;document.querySelector('.viewport').style.height=790*scale+'px'}addEventListener('resize',scale);scale();